mapper.select:
SELECT X.INV_NO, X.INVOICE_DATE, X.STATUS, X.LEGACY_IV_SERIAL, X.PROCESS_TYPE, X.LEGACY_PO_NO, X.LEGACY_PO_SEQ, X.BUYER_ITEM_NO, X.INV_QTY, X.PO_CREATE_DATE, X.RD_DATE, X.AGENT, X.PO_NO, X.PO_SEQ, X.ITEM_QTY, X.IV_QTY, X.GR_QTY, X.CHANGE_DATE, X.CHANGE_TIME, X.DELIVERY_DATE, X.DELIVERY_QTY FROM ( SELECT C.INV_NO AS INV_NO, C.INVOICE_DATE AS INVOICE_DATE, DECODE(C.STATUS,'C','신규','R','수정','D','삭제') AS STATUS, D.LEGACY_IV_SERIAL AS LEGACY_IV_SERIAL, DECODE(A.PROCESS_TYPE,0,'직납',2,'TR') AS PROCESS_TYPE, A.LEGACY_PO_NO AS LEGACY_PO_NO, A.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, A.BUYER_ITEM_NO AS BUYER_ITEM_NO, C.INV_QTY AS INV_QTY, B.PO_CREATE_DATE AS PO_CREATE_DATE, A.RD_DATE AS RD_DATE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = B.AGENT) AS AGENT, A.PO_NO AS PO_NO, A.PO_SEQ AS PO_SEQ, A.ITEM_QTY AS ITEM_QTY, A.IV_QTY AS IV_QTY, A.GR_QTY AS GR_QTY, D.CHANGE_DATE AS CHANGE_DATE, D.CHANGE_TIME AS CHANGE_TIME, C.DELIVERY_DATE AS DELIVERY_DATE, C.DELIVERY_QTY AS DELIVERY_QTY FROM ICOMPODT A, ICOMPOHD B, ICOMIVDT C, ICOMIVHD D WHERE A.BUYER = 'KRDAEW0016' AND A.STATUS <> 'D' AND A.PROCESS_TYPE <> '2' AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.BUYER = C.BUYER AND A.PO_NO = C.PO_NO AND A.PO_SEQ= C.PO_SEQ AND C.BUYER = D.BUYER AND C.INV_NO= D.INV_NO
AND D.LEGACY_IV_SERIAL = #{st_legacy_iv_serial}
AND A.LEGACY_PO_NO = #{st_legacy_po_no}
AND A.LEGACY_PO_SEQ= DECODE(TRIM(#{st_legacy_po_seq}),NULL,A.LEGACY_PO_SEQ,#{st_legacy_po_seq})
UNION ALL SELECT C.INV_NO AS INV_NO, C.INV_DATE AS INVOICE_DATE, DECODE(C.STATUS,'C','신규','R','수정','D','삭제') AS STATUS, C.LEGACY_IV_SERIAL AS LEGACY_IV_SERIAL, DECODE(A.PROCESS_TYPE,0,'직납',2,'TR') AS PROCESS_TYPE, A.LEGACY_PO_NO AS LEGACY_PO_NO, A.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, A.BUYER_ITEM_NO AS BUYER_ITEM_NO, C.INV_QTY AS INV_QTY, B.PO_CREATE_DATE AS PO_CREATE_DATE, A.RD_DATE AS RD_DATE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = B.AGENT) AS AGENT, A.PO_NO AS PO_NO, A.PO_SEQ AS PO_SEQ, A.ITEM_QTY AS ITEM_QTY, A.IV_QTY AS IV_QTY, A.GR_QTY AS GR_QTY, C.CHANGE_DATE AS CHANGE_DATE, C.CHANGE_TIME AS CHANGE_TIME, C.DELIVERY_DATE AS DELIVERY_DATE, C.DELIVERY_QTY AS DELIVERY_QTY FROM ICOMPODT A, ICOMPOHD B, WMSIVDT C WHERE A.BUYER = 'KRDAEW0016' AND A.STATUS <> 'D' AND A.PROCESS_TYPE = '2' AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.BUYER = C.BUYER AND A.PO_NO = C.PO_NO AND A.PO_SEQ= C.PO_SEQ
AND C.LEGACY_IV_SERIAL = #{st_legacy_iv_serial}
AND A.LEGACY_PO_NO = #{st_legacy_po_no}
AND A.LEGACY_PO_SEQ= DECODE(TRIM(#{st_legacy_po_seq}),NULL,A.LEGACY_PO_SEQ,#{st_legacy_po_seq})
) X ORDER BY LEGACY_PO_NO,LEGACY_PO_SEQ,LEGACY_IV_SERIAL
